     1	package pousada.report;
     2	
     3	import java.time.YearMonth;
     4	import java.time.format.DateTimeParseException;
     5	import java.util.Comparator;
     6	import java.util.List;
     7	import java.util.function.Predicate;
     8	import pousada.db.ReservationRepository;
     9	import pousada.domain.AppException;
    10	import pousada.domain.ErrorCode;
    11	import pousada.domain.Reservation;
    12	
    13	/** Base dos relatórios de um mês: reservas que começam no mês, em ordem de entrada e número. */
    14	abstract class MonthlyReport extends Report<YearMonth> {
    15	    private final ReservationRepository reservations;
    16	
    17	    MonthlyReport(ReservationRepository reservations) {
    18	        this.reservations = reservations;
    19	    }
    20	
    21	    @Override
    22	    public String parameter() {
    23	        return "month";
    24	    }
    25	
    26	    @Override
    27	    protected YearMonth parse(String raw) {
    28	        try {
    29	            if (raw == null || !raw.matches("\\d{4}-\\d{2}")) {
    30	                throw new DateTimeParseException("mês", String.valueOf(raw), 0);
    31	            }
    32	            return YearMonth.parse(raw);
    33	        } catch (DateTimeParseException e) {
    34	            throw new AppException(ErrorCode.INVALID_REQUEST, "Mês inválido, use o formato 2027-07");
    35	        }
    36	    }
    37	
    38	    protected List<Reservation> startingIn(YearMonth month, Predicate<Reservation> filter) {
    39	        return reservations.findAll().stream()
    40	                .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
    41	                .filter(filter)
    42	                .sorted(Comparator.comparing(Reservation::getCheckIn).thenComparing(Reservation::getId))
    43	                .toList();
    44	    }
    45	
    46	    /** Reservas que deixaram dinheiro com a pousada. */
    47	    protected static boolean keptMoney(Reservation r) {
    48	        return r.retained().signum() > 0;
    49	    }
    50	}
