     1	package pousada.report;
     2	
     3	import java.time.LocalDate;
     4	import java.time.format.DateTimeParseException;
     5	import java.util.Comparator;
     6	import java.util.List;
     7	import pousada.db.ReservationRepository;
     8	import pousada.domain.AppException;
     9	import pousada.domain.ErrorCode;
    10	import pousada.domain.Reservation;
    11	import pousada.domain.RoomCatalog;
    12	
    13	public class OccupancyReport extends Report<LocalDate> {
    14	    private final ReservationRepository reservations;
    15	    private final RoomCatalog rooms;
    16	
    17	    public OccupancyReport(ReservationRepository reservations, RoomCatalog rooms) {
    18	        this.reservations = reservations;
    19	        this.rooms = rooms;
    20	    }
    21	
    22	    @Override
    23	    public String name() {
    24	        return "occupancy";
    25	    }
    26	
    27	    @Override
    28	    public String parameter() {
    29	        return "date";
    30	    }
    31	
    32	    @Override
    33	    protected LocalDate parse(String raw) {
    34	        try {
    35	            if (raw == null) {
    36	                throw new DateTimeParseException("data", "", 0);
    37	            }
    38	            return LocalDate.parse(raw);
    39	        } catch (DateTimeParseException e) {
    40	            throw new AppException(ErrorCode.INVALID_REQUEST, "Data inválida, use o formato 2027-07-10");
    41	        }
    42	    }
    43	
    44	    @Override
    45	    protected Table table(LocalDate night) {
    46	        List<Reservation> occupying = reservations.findAll().stream()
    47	                .filter(r -> r.occupies(night))
    48	                .sorted(Comparator.comparingInt(Reservation::getRoomNumber).thenComparing(Reservation::getId))
    49	                .toList();
    50	        List<String> rows = occupying.stream()
    51	                .map(r -> String.join(",", String.valueOf(r.getRoomNumber()),
    52	                        rooms.get(r.getRoomNumber()).type().name(), String.valueOf(r.getId()),
    53	                        r.getCheckIn().toString(), r.getCheckOut().toString()))
    54	                .toList();
    55	        long occupiedRooms = occupying.stream().map(Reservation::getRoomNumber).distinct().count();
    56	        return new Table("room,type,reservation,check_in,check_out", rows,
    57	                "total," + occupiedRooms + "/" + rooms.all().size());
    58	    }
    59	}
