     1	package pousada.report;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.YearMonth;
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	import pousada.db.ReservationRepository;
     8	import pousada.domain.Money;
     9	import pousada.domain.RatePlan;
    10	import pousada.domain.Reservation;
    11	
    12	public class RatePlanReport extends MonthlyReport {
    13	    public RatePlanReport(ReservationRepository reservations) {
    14	        super(reservations);
    15	    }
    16	
    17	    @Override
    18	    public String name() {
    19	        return "rate-plans";
    20	    }
    21	
    22	    @Override
    23	    protected Table table(YearMonth month) {
    24	        List<Reservation> list = startingIn(month, MonthlyReport::keptMoney);
    25	        List<String> rows = new ArrayList<>();
    26	        for (RatePlan plan : RatePlan.values()) {
    27	            List<Reservation> ofPlan = list.stream().filter(r -> r.getRatePlan() == plan).toList();
    28	            BigDecimal amount = ofPlan.stream().map(Reservation::retained).reduce(BigDecimal.ZERO, BigDecimal::add);
    29	            rows.add(plan + "," + ofPlan.size() + "," + Money.plain(amount));
    30	        }
    31	        BigDecimal sum = list.stream().map(Reservation::retained).reduce(BigDecimal.ZERO, BigDecimal::add);
    32	        return new Table("rate_plan,reservations,amount", rows, "total," + list.size() + "," + Money.plain(sum));
    33	    }
    34	}
=== src/main/java/pousada/report/Report.java
     1	package pousada.report;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	/**
     7	 * Sequência única de todo relatório CSV: título, cabeçalho, linhas e total.
     8	 * Cada relatório só diz o seu nome, o parâmetro que recebe e o conteúdo da tabela.
     9	 * Mudar o jeito dos relatórios (ex.: uma linha final com a data) é mudar apenas {@link #generate}.
    10	 */
    11	public abstract class Report<P> {
    12	    static final String PROPERTY_NAME = "Pousada Maré Alta";
    13	
    14	    public record Table(String header, List<String> rows, String total) {}
    15	
    16	    /** Nome usado na URL e no título (occupancy, revenue, ...). */
    17	    public abstract String name();
    18	
    19	    /** Nome do parâmetro de consulta (date, month, ...). */
    20	    public abstract String parameter();
    21	
    22	    protected abstract P parse(String raw);
    23	
    24	    protected abstract Table table(P period);
    25	
    26	    public final String generate(String raw) {
    27	        P period = parse(raw);
    28	        Table table = table(period);
    29	        List<String> lines = new ArrayList<>();
    30	        lines.add(PROPERTY_NAME + "," + name() + "," + period);
    31	        lines.add(table.header());
    32	        lines.addAll(table.rows());
    33	        lines.add(table.total());
    34	        return String.join("\n", lines) + "\n";
    35	    }
    36	}
