    33	                        String.valueOf(r.getNights()), Money.plain(tax(r))))
    34	                .toList();
    35	        BigDecimal sum = list.stream().map(this::tax).reduce(BigDecimal.ZERO, BigDecimal::add);
    36	        return new Table("reservation,room,check_in,check_out,guests,nights,tax", rows,
    37	                "total," + Money.plain(sum));
