     1	package pousada.db;
     2	
     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	import java.util.function.Supplier;
     8	
     9	/** Acesso ao banco; dentro de transaction() todas as consultas usam a mesma conexão. */
    10	public class Database {
    11	    public interface SqlFunction<T> {
    12	        T apply(Connection connection) throws SQLException;
    13	    }
    14	
    15	    private final String url;
    16	    private final String user;
    17	    private final String password;
    18	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    19	
    20	    public Database(String url, String user, String password) {
    21	        this.url = url;
    22	        this.user = user;
    23	        this.password = password;
    24	    }
    25	
    26	    private Connection open() throws SQLException {
    27	        return DriverManager.getConnection(url, user, password);
    28	    }
    29	
    30	    public <T> T query(SqlFunction<T> work) {
    31	        Connection shared = current.get();
    32	        try {
    33	            if (shared != null) {
    34	                return work.apply(shared);
    35	            }
    36	            try (Connection connection = open()) {
    37	                return work.apply(connection);
    38	            }
    39	        } catch (SQLException e) {
    40	            throw new IllegalStateException(e);
    41	        }
    42	    }
    43	
    44	    public <T> T transaction(Supplier<T> work) {
    45	        if (current.get() != null) {
    46	            return work.get();
    47	        }
    48	        try (Connection connection = open()) {
    49	            connection.setAutoCommit(false);
    50	            current.set(connection);
    51	            try {
    52	                T result = work.get();
    53	                connection.commit();
    54	                return result;
    55	            } catch (RuntimeException e) {
    56	                connection.rollback();
    57	                throw e;
    58	            } finally {
    59	                current.remove();
    60	            }
    61	        } catch (SQLException e) {
    62	            throw new IllegalStateException(e);
    63	        }
    64	    }
    65	
    66	    /** Cria o que o sistema precisa num banco vazio; não mexe no que já existe. */
    67	    public void createSchema() {
    68	        query(c -> {
    69	            try (Statement st = c.createStatement()) {
    70	                st.execute("""
    71	                        CREATE TABLE IF NOT EXISTS reservations (
    72	                            id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    73	                            room_number INTEGER NOT NULL,
    74	                            guest_name VARCHAR(200) NOT NULL,
    75	                            guest_email VARCHAR(200) NOT NULL,
    76	                            guest_cpf VARCHAR(30) NOT NULL,
    77	                            check_in DATE NOT NULL,
    78	                            check_out DATE NOT NULL,
    79	                            guests INTEGER NOT NULL,
    80	                            rate_plan VARCHAR(30) NOT NULL,
    81	                            nights INTEGER NOT NULL,
    82	                            subtotal NUMERIC(12,2) NOT NULL,
    83	                            discount NUMERIC(12,2) NOT NULL,
    84	                            total NUMERIC(12,2) NOT NULL,
    85	                            status VARCHAR(30) NOT NULL,
    86	                            amount_paid NUMERIC(12,2) NOT NULL,
    87	                            refund NUMERIC(12,2)
    88	                        )""");
    89	                st.execute("""
    90	                        CREATE TABLE IF NOT EXISTS messages (
    91	                            id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    92	                            channel VARCHAR(20) NOT NULL,
    93	                            recipient VARCHAR(200) NOT NULL,
    94	                            subject VARCHAR(500) NOT NULL,
    95	                            body VARCHAR(10000) NOT NULL
    96	                        )""");
    97	            }
    98	            return null;
    99	        });
   100	    }
   101	
   102	    /** Espera o banco aceitar conexões (ele pode subir junto com o sistema). */
   103	    public void createSchemaWithRetry(int attempts) {
   104	        for (int i = 1; ; i++) {
   105	            try {
   106	                createSchema();
   107	                return;
   108	            } catch (RuntimeException e) {
   109	                if (i >= attempts) {
   110	                    throw e;
   111	                }
   112	                try {
   113	                    Thread.sleep(1000);
   114	                } catch (InterruptedException ie) {
   115	                    Thread.currentThread().interrupt();
   116	                    throw e;
   117	                }
   118	            }
   119	        }
   120	    }
   121	}
