     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {}
    11	
    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    15	    public static boolean highSeason(LocalDate night) {
    16	        Month month = night.getMonth();
    17	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    18	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    19	    }
    20	
    21	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    22	        return highSeason(night) ? Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR)) : room.nightlyRate();
    23	    }
    24	
    25	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    26	        BigDecimal subtotal = Money.round(BigDecimal.ZERO);
    27	        int nights = 0;
    28	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    29	            subtotal = subtotal.add(nightPrice(room, night));
    30	            nights++;
    31	        }
    32	        BigDecimal discount = plan.discount(subtotal);
    33	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    34	    }
    35	}
