    28	    public void insert(Reservation r) {
    29	        db.query(c -> {
    30	            try (PreparedStatement ps = c.prepareStatement("""
    31	                    INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    32	                        guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    33	                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
    34	                ps.setInt(1, r.getRoomNumber());
