 18	
 19	class SystemTest {
 20	    static Javalin app;
 21	    static String base;
 22	    static final HttpClient http = HttpClient.newHttpClient();
 23	
 24	    @BeforeAll
 25	    static void start() {
 26	        Database db = new Database("jdbc:h2:mem:test;DB_CLOSE_DELAY=-1", "sa", "");
 27	        db.createSchema();
 28	        app = Main.build(db).start(0);
 29	        base = "http://localhost:" + app.port();
 30	    }
 31	
 32	    @AfterAll
 33	    static void stop() {
 34	        app.stop();
 35	    }
 36	
 37	    static HttpResponse<String> call(String method, String path, String body) throws Exception {
 38	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 39	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 40	        return http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 41	    }
 42	
 43	    static String reservation(int room, String in, String out, int guests, String plan) {
 44	        return """
 45	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@ex.com","guestCpf":"11122233344",
 46	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
 47	    }
 48	
 49	    @Test
