 56	                pousada.domain.RatePlan.NON_REFUNDABLE);
 57	        assertEquals(Money.of("37.48"), nr.discount());
 58	        assertEquals(Money.of("212.42"), nr.total());
 59	    }
 60	
 61	    @Test
 62	    void fullFlowAndReports() throws Exception {
 63	        var created = call("POST", "/reservations", reservation(201, "2027-03-10", "2027-03-12", 2, "STANDARD"));
 64	        assertEquals(201, created.statusCode());
 65	        assertTrue(created.body().contains("\"total\":779.80"), created.body());
 66	        assertTrue(created.body().contains("\"refund\":null"));
 67	
 68	        assertEquals(409, call("POST", "/reservations", reservation(201, "2027-03-11", "2027-03-13", 2, "STANDARD")).statusCode());
 69	        assertEquals(422, call("POST", "/reservations", reservation(101, "2027-03-11", "2027-03-13", 3, "STANDARD")).statusCode());
 70	        assertEquals(400, call("POST", "/reservations", "nao e json").statusCode());
 71	        assertEquals(404, call("POST", "/reservations", reservation(999, "2027-03-11", "2027-03-13", 1, "STANDARD")).statusCode());
 72	        assertEquals(409, call("GET", "/reservations/1/document", null).statusCode());
 73	        assertEquals(409, call("POST", "/reservations/1/check-in", null).statusCode());
 74	
 75	        assertEquals(200, call("POST", "/reservations/1/confirmation", null).statusCode());
 76	        var messages = call("GET", "/messages", null).body();
 77	        assertTrue(messages.contains("Reserva confirmada - Pousada Maré Alta"));
 78	        assertTrue(messages.contains("Diárias: R$ 779,80"), messages);
 79	
 80	        var doc = call("GET", "/reservations/1/document", null).body();
 81	        assertTrue(doc.contains("\"title\":\"Comprovante de reserva\""));
 82	
 83	        var occupancy = call("GET", "/reports/occupancy?date=2027-03-10", null);
