 85	        assertEquals("Pousada Maré Alta,occupancy,2027-03-10\nroom,type,reservation,check_in,check_out\n"
 86	                + "201,DELUXE,1,2027-03-10,2027-03-12\ntotal,1/5\n", occupancy.body());
 87	        assertTrue(call("GET", "/reports/occupancy?date=2027-03-12", null).body().endsWith("total,0/5\n"));
 88	
 89	        call("POST", "/reservations", reservation(301, "2027-03-05", "2027-03-08", 2, "NON_REFUNDABLE"));
 90	        call("POST", "/reservations/2/confirmation", null);
 91	        var cancelled = call("POST", "/reservations/2/cancellation", null);
 92	        assertTrue(cancelled.body().contains("\"refund\":0.00"), cancelled.body());
 93	
 94	        assertEquals("Pousada Maré Alta,revenue,2027-03\nreservation,room,check_in,check_out,status,amount\n"
 95	                        + "2,301,2027-03-05,2027-03-08,CANCELLED,1478.74\n1,201,2027-03-10,2027-03-12,CONFIRMED,779.80\n"
 96	                        + "total,2258.54\n",
 97	                call("GET", "/reports/revenue?month=2027-03", null).body());
 98	        assertEquals("Pousada Maré Alta,tourism-tax,2027-03\nreservation,room,check_in,check_out,guests,nights,tax\n"
 99	                        + "1,201,2027-03-10,2027-03-12,2,2,18.00\ntotal,18.00\n",
100	                call("GET", "/reports/tourism-tax?month=2027-03", null).body());
101	        assertEquals("Pousada Maré Alta,rate-plans,2027-03\nrate_plan,reservations,amount\n"
102	                        + "STANDARD,1,779.80\nNON_REFUNDABLE,1,1478.74\ntotal,2,2258.54\n",
103	                call("GET", "/reports/rate-plans?month=2027-03", null).body());
104	        assertEquals(400, call("GET", "/reports/revenue?month=2027-3", null).statusCode());
105	
106	        assertEquals(200, call("POST", "/reservations/1/check-in", null).statusCode());
107	        assertTrue(call("POST", "/reservations/1/check-out", null).body().contains("\"nights\":2"));
108	        assertEquals(404, call("GET", "/reservations/abc", null).statusCode());
109	    }
110	}

